                if ticker == "SPY":
                    self.spy_sma.Update(bar.EndTime, bar.Close)
                elif ticker == "AAPL":
                    self.aapl_rsi.Update(bar.EndTime, bar.Close)
                    if self.previous_aapl_close is not None:
                        if bar.Close < self.previous_aapl_close:
                            self.aapl_red_streak += 1
                        else:
                            self.aapl_red_streak = 0
                    self.previous_aapl_close = bar.Close

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = bars[self.symbols["SPY"]].Close
        aapl_close = bars[self.symbols["AAPL"]].Close

        spy_crossed_below = (
            self.spy_sma.Previous.Value != 0 and
            self.spy_sma.Previous.Value >= 0 and
            self.spy_sma.Previous.Value >= self.spy_sma.Previous.Value and
            self.spy_sma.Previous.Value >= 0 and
            self.Securities[self.symbols["SPY"]].Price < self.spy_sma.Current.Value and
            self.spy_sma.Previous.Value <= self.spy_sma.Previous.Value
        )

        previous_spy_close = self.spy_sma.Previous.Value
        current_spy_sma = self.spy_sma.Current.Value
        previous_spy_sma = self.spy_sma.Previous.Value

        if self.strategy_a_shares > 0:
            if previous_spy_close >= previous_spy_sma and spy_close < current_spy_sma:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if previous_spy_close <= previous_spy_sma and spy_close > current_spy_sma:
                shares = int(math.floor((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close))
                if shares > 0:
                    self.MarketOrder(self.symbols["SPY"], shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                shares = int(math.floor(20_000 / aapl_close))
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares
