class ParallelSmaAndRsiAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.sma_period = 50
        self.spy_sma = self.SMA(self.symbols["SPY"], self.sma_period, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.pending_orders = {}

    def OnData(self, data: Slice):
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[self.symbols["SPY"]]
        aapl_bar = data.Bars[self.symbols["AAPL"]]

        if self.previous_aapl_close is not None:
            if aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady

        if indicators_ready:
            spy_crosses_below = (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_bar.Close < self.spy_sma.Current.Value
            )

            aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

            # Sells are evaluated before buys.
            if self.strategy_a_shares > 0 and spy_crosses_below:
                self.SubmitLotOrder("A", self.symbols["SPY"], -self.strategy_a_shares)

            if self.strategy_b_shares > 0 and aapl_rsi_above_60:
                self.SubmitLotOrder("B", self.symbols["AAPL"], -self.strategy_b_shares)

            spy_crosses_above = (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_bar.Close > self.spy_sma.Current.Value
            )

            if self.strategy_a_shares == 0 and "A" not in self.pending_orders and spy_crosses_above:
                desired_value = self.Portfolio.TotalPortfolioValue * 0.40
                quantity = int(desired_value / spy_bar.Close)
                affordable_quantity = int(self.Portfolio.Cash / spy_bar.Close)
                quantity = min(quantity, affordable_quantity)

                if quantity > 0:
                    self.SubmitLotOrder("A", self.symbols["SPY"], quantity)

            if (
                self.strategy_b_shares == 0
                and "B" not in self.pending_orders
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20000
            ):
                quantity = int(20000 / aapl_bar.Close)
                if quantity > 0:
                    self.SubmitLotOrder("B", self.symbols["AAPL"], quantity)

        self.previous_spy_close = spy_bar.Close
        self.previous_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None
        self.previous_aapl_close = aapl_bar.Close

    def SubmitLotOrder(self, lot_name, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[lot_name] = ticket.OrderId

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status not in [OrderStatus.Filled, OrderStatus.PartiallyFilled]:
            if orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                for lot_name, order_id in list(self.pending_orders.items()):
                    if order_id == orderEvent.OrderId:
                        del self.pending_orders[lot_name]
            return

        if orderEvent.Symbol == self.symbols["SPY"]:
            self.strategy_a_shares += orderEvent.FillQuantity
            if self.strategy_a_shares < 0:
                self.strategy_a_shares = 0

            if orderEvent.Status == OrderStatus.Filled:
                self.pending_orders.pop("A", None)

        elif orderEvent.Symbol == self.symbols["AAPL"]:
            self.strategy_b_shares += orderEvent.FillQuantity
            if self.strategy_b_shares < 0:
                self.strategy_b_shares = 0

            if orderEvent.Status == OrderStatus.Filled:
                self.pending_orders.pop("B", None)
