            current_sma = self.spy_sma.Current.Value

        if present["AAPL"]:
            aapl_close = data.Bars[self.aapl].Close
            current_rsi = self.aapl_rsi.Current.Value

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        all_bars_present = all(present.values())

        if (
            all_bars_present
            and self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.spy_previous_close is not None
            and self.spy_previous_sma is not None
            and self.aapl_previous_close is not None
            and self.aapl_previous_rsi is not None
        ):
            spy_crosses_above = (
                self.spy_previous_close <= self.spy_previous_sma
                and spy_close > current_sma
            )
            spy_crosses_below = (
                self.spy_previous_close >= self.spy_previous_sma
                and spy_close < current_sma
            )
            rsi_crosses_above_60 = (
                self.aapl_previous_rsi <= 60
                and current_rsi > 60
            )

            if self.strategy_a_lot > 0 and spy_crosses_below:
                self.MarketOrder(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if self.strategy_b_lot > 0 and rsi_crosses_above_60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

            if self.strategy_a_lot == 0 and spy_crosses_above:
                shares = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_lot = shares

            if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20_000:
                    shares = int(20_000 // aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.strategy_b_lot = shares

        if present["SPY"]:
            self.spy_previous_close = spy_close
            if self.spy_sma.IsReady:
                self.spy_previous_sma = current_sma

        if present["AAPL"]:
            self.aapl_previous_close = aapl_close
            if self.aapl_rsi.IsReady:
                self.aapl_previous_rsi = current_rsi
